@extends('layouts.app') @section('title','Раздача питания') @section('content')<style>.mealbtn{min-height:58px;font-size:1.1rem}#result{font-size:1.25rem}</style><h1 class="h4">📷 Раздача питания</h1><div class="row g-2"><div class="col-6 col-md-3"><button class="btn btn-success w-100 mealbtn type" data-type="breakfast">☕ Завтрак</button></div><div class="col-6 col-md-3"><button class="btn btn-outline-primary w-100 mealbtn type" data-type="lunch">🍲 Обед</button></div><div class="col-6 col-md-3"><button class="btn btn-outline-primary w-100 mealbtn type" data-type="snack">🥪 Полдник</button></div><div class="col-6 col-md-3"><button class="btn btn-outline-primary w-100 mealbtn type" data-type="dinner">🍽 Ужин</button></div></div><button id="cam" class="btn btn-dark w-100 mealbtn mt-2">📷 Сканировать QR</button><video id="video" playsinline class="w-100 mt-2 rounded" style="background:#111;max-height:45vh"></video><form id="manual" class="mt-2"><input id="token" class="form-control form-control-lg" placeholder="QR / сканер / токен"><button class="btn btn-secondary w-100 mealbtn mt-2">ВЫДАТЬ</button></form><div id="result" class="alert d-none mt-3"></div><h2 class="h6 mt-4">Последние выдачи</h2>@foreach($recent as $x)<div class="border-bottom py-2">{{$x->issued_at}} · <b>{{$x->last_name}} {{$x->first_name}}</b> · {{$x->meal_type}} · {{$x->category_name}}</div>@endforeach<script>let meal='breakfast';document.querySelectorAll('.type').forEach(b=>b.onclick=()=>{meal=b.dataset.type;document.querySelectorAll('.type').forEach(x=>x.className='btn btn-outline-primary w-100 mealbtn type');b.className='btn btn-success w-100 mealbtn type'});async function send(t){let r=await fetch('{{route('canteen.scan')}}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{csrf_token()}}'},body:JSON.stringify({token:t,meal_type:meal})});let j=await r.json();result.className='alert mt-3 '+(j.ok?'alert-success':'alert-danger');result.innerHTML=j.ok?'<b>'+j.student+'</b><br>'+j.category+' · '+j.meal:(j.message||'Ошибка');}manual.onsubmit=e=>{e.preventDefault();send(token.value.trim());token.value=''};cam.onclick=async()=>{if(!('BarcodeDetector'in window)){alert('Используйте аппаратный QR-сканер или ввод кода.');return}let s=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});video.srcObject=s;await video.play();let d=new BarcodeDetector({formats:['qr_code']});setInterval(async()=>{try{let x=await d.detect(video);if(x.length)await send(x[0].rawValue)}catch(e){}},1000)};</script>@endsection